import java.io.BufferedReader;
import java.io.InputStreamReader;

public class Main {
    public static void main(String[] args) throws Exception {
        String plate = new BufferedReader(new InputStreamReader(System.in)).readLine();
        int result = 0;

        if (plate.length() == 8
                && isUppercase(plate, 0)
                && isUppercase(plate, 1)
                && isUppercase(plate, 2)
                && plate.charAt(3) == '-'
                && isDigit(plate, 4)
                && isDigit(plate, 5)
                && isDigit(plate, 6)
                && isDigit(plate, 7)) {
            result = 1;
        } else if (plate.length() == 7
                && isUppercase(plate, 0)
                && isUppercase(plate, 1)
                && isUppercase(plate, 2)
                && isDigit(plate, 3)
                && isUppercase(plate, 4)
                && isDigit(plate, 5)
                && isDigit(plate, 6)) {
            result = 2;
        }

        System.out.println(result);
    }

    private static boolean isUppercase(String s, int index) {
        char c = s.charAt(index);
        return c >= 'A' && c <= 'Z';
    }

    private static boolean isDigit(String s, int index) {
        char c = s.charAt(index);
        return c >= '0' && c <= '9';
    }
}
